def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float))

    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pair(obj, default=None):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
            return obj[0], obj[1]
        if isinstance(obj, dict):
            x = obj.get("x", obj.get("col", obj.get("c")))
            y = obj.get("y", obj.get("row", obj.get("r")))
            if is_num(x) and is_num(y):
                return x, y
        return default

    def clamp_move(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def extract_positions(value):
        out = []
        if isinstance(value, dict):
            for key in ("positions", "cells", "items", "targets", "points", "cells_list", "tiles"):
                if key in value:
                    value = value.get(key)
                    break
        if isinstance(value, (list, tuple)):
            for item in value:
                p = pair(item, None)
                if p is not None:
                    out.append(p)
                elif isinstance(item, dict):
                    for key in ("position", "pos", "loc", "location"):
                        p = pair(item.get(key), None)
                        if p is not None:
                            out.append(p)
                            break
        return out

    obs = observation if isinstance(observation, dict) else {}
    sx, sy = pair(obs.get("self_position", obs.get("position", obs.get("self", (0, 0)))), (0, 0))
    ox, oy = pair(obs.get("opponent_position", obs.get("enemy_position", obs.get("opponent", (sx, sy)))), (sx, sy))
    w = obs.get("grid_width", obs.get("width", 0))
    h = obs.get("grid_height", obs.get("height", 0))

    # Detect common mode hints from fields
    env = obs.get("environment_name", obs.get("mode", ""))

    if env == "pursuit_evasion":
        role = obs.get("self_role", obs.get("role", "pursuer"))
        if role == "pursuer":
            return clamp_move((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return clamp_move((sx, sy), target)

    if env == "territory_control":
        candidates = []
        for key in ("frontier_cells", "target_cells", "unclaimed_cells", "opponent_territory", "enemy_cells", "neutral_cells", "border_cells"):
            cells = extract_positions(obs.get(key, []))
            if cells:
                candidates = cells
                break
        if candidates:
            best = min(candidates, key=lambda c: (manhattan(c, (sx, sy)), manhattan(c, (ox, oy))))
            return clamp_move((sx, sy), best)
        return [sgn(ox - sx), sgn(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]

    resources = []
    for key in ("resources", "resource_positions", "targets", "food", "collectibles", "items", "pickups", "goal_cells"):
        items = extract_positions(obs.get(key, []))
        if items:
            resources = items
            break

    if resources:
